#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRpcClient: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = RpcClient

    public static func lift(_ handle: UInt64) throws -> RpcClient {
        return RpcClient(unsafeFromHandle: handle)
    }

    public static func lower(_ value: RpcClient) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RpcClient {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: RpcClient, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRpcClient_lift(_ handle: UInt64) throws -> RpcClient {
    return try FfiConverterTypeRpcClient.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRpcClient_lower(_ value: RpcClient) -> UInt64 {
    return FfiConverterTypeRpcClient.lower(value)
}






public protocol RpcErrorProtocol: AnyObject, Sendable {
    
    /**
     * Returns the account error if the underlying error is an account error.
     */
    func accountError()  -> AccountCommandError?
    
    /**
     * Print the underlying error chain
     */
    func displayChain()  -> String
    
}
open class RpcError: RpcErrorProtocol, @unchecked Sendable, Swift.Error, Foundation.LocalizedError, CustomStringConvertible {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
