    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceTunnelEventObserver] = [UniffiVTableCallbackInterfaceTunnelEventObserver(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeTunnelEventObserver.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface TunnelEventObserver: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTunnelEventObserver.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface TunnelEventObserver: handle missing in uniffiClone")
            }
        },
        onTunnelEvent: { (
            uniffiHandle: UInt64,
            event: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeTunnelEventObserver.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onTunnelEvent(
